# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: start.gg's Ultimate characters as stored data (pkgs/ds/data/startgg_char.parquet),
# so a lookup doesn't spend a start.gg request on them. Ultimate's roster is final, so the
# table only changes if start.gg renumbers; refresh it with `uv run ds data startgg-char`.
# Usage: `stored_characters()` -> {start.gg id: Character}, or None without the table.
# ---------------------------------------------------------------------------
# Data storage, not a cache: written on purpose by a command, read fresh on every call (a
# small file), never refilled behind the caller's back ("Caching Policy", .agents/agents.md).
from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING

import polars as pl

from ds.data.chars import CharGroup
from ds.data.raw.startgg.api import startgg_character

if TYPE_CHECKING:
    from ds.data.raw.startgg.models import Character

__all__ = ["CHAR_GROUP_DTYPE", "STARTGG_CHAR_PARQUET", "characters_table", "stored_characters"]

# one row per start.gg character pick (Pokemon Trainer is one pick there, three fighters in
# char.parquet, so this can't be a column of char.parquet): startgg_id, name, char_group
STARTGG_CHAR_PARQUET = Path(__file__).resolve().parent.parent / "startgg_char.parquet"


# the column type of `char_group`: exactly CharGroup's members (generated from char.parquet),
# so the table can't hold a pick the rest of the code doesn't know; writing one fails
CHAR_GROUP_DTYPE = pl.Enum([group.value for group in CharGroup])


def characters_table(characters: dict[int, Character]) -> pl.DataFrame:
    """The table to store, from `ds.data.raw.startgg.videogame_characters()`

    Raises if a `char_group` isn't a CharGroup member (the column is CHAR_GROUP_DTYPE).
    """
    rows = [{"startgg_id": c.id, "name": c.name, "char_group": c.char_group} for c in characters.values()]
    schema = {"startgg_id": pl.Int64, "name": pl.String, "char_group": CHAR_GROUP_DTYPE}
    return pl.DataFrame(rows, schema=schema).sort("startgg_id")


def stored_characters(path: Path = STARTGG_CHAR_PARQUET) -> dict[int, Character] | None:
    """start.gg's characters by id from the stored table; None when it hasn't been written

    The same Characters `videogame_characters()` returns: `char_group` and `char_icon` are
    worked out from the name as there, so a fix to the name matching applies without a refresh.
    """
    if not path.exists():
        return None
    return {
        startgg_id: startgg_character(startgg_id, name)
        for startgg_id, name in pl.read_parquet(path, columns=["startgg_id", "name"]).iter_rows()
    }
